// Generated by scripts/gen-schema.mjs from server/schema.prisma
export default "generator client {\r\n  provider = \"prisma-client-js\"\r\n}\r\n\r\ndatasource db {\r\n  provider = \"mysql\"\r\n  url      = env(\"DATABASE_URL\")\r\n}\r\n\r\nmodel User {\r\n  id          Int         @id @default(autoincrement()) // Use Int for IDs with auto increment\r\n  email       String      @unique\r\n  username    String      @unique\r\n  password    String\r\n  avatar      String?\r\n  role        Role        @default(client)\r\n  // Which platform the account was opened for: a marketplace account, or an\r\n  // agency account (registered as an agency; signs in on the agency platform\r\n  // only, first to follow its application, then as the agency's owner)\r\n  accountType AccountType @default(individual)\r\n  createdAt   DateTime    @default(now())\r\n  // listings this account is responsible for: an individual's own, or the\r\n  // agency listings assigned to this agent\r\n  posts       Post[]\r\n  savedPosts  SavedPost[] // Relation to SavedPost model\r\n  chats       ChatUser[] // Join table for many-to-many relation with Chat\r\n\r\n  // 👇 Add these agency-specific fields\r\n  agencyName String?\r\n  phone      String?\r\n  location   String?\r\n  website    String?\r\n  about      String?\r\n\r\n  inquiries         Inquiry[] @relation(\"InquiryClient\")\r\n  inquiriesReceived Inquiry[] @relation(\"InquiryOwner\")\r\n  inquiriesAssigned Inquiry[] @relation(\"InquiryAssignee\")\r\n  postsCreated      Post[]    @relation(\"PostCreator\")\r\n\r\n  // Account state managed from the admin dashboard\r\n  status            UserStatus @default(active)\r\n  statusReason      String?    @db.Text\r\n  verified          Boolean    @default(false)\r\n  lastLoginAt       DateTime?\r\n  // Sessions issued before this are refused (password change or reset)\r\n  passwordChangedAt DateTime?\r\n  updatedAt         DateTime   @default(now()) @updatedAt\r\n\r\n  // Agency membership: the owner, managers and agents all point at the agency\r\n  agencyId        Int?\r\n  agency          Agency?            @relation(\"AgencyMembers\", fields: [agencyId], references: [id], onDelete: SetNull)\r\n  agencyRole      AgencyRole?\r\n  // The agency can switch a member off without touching their Bayti account\r\n  agencyActive    Boolean            @default(true)\r\n  ownedAgency     Agency?            @relation(\"AgencyOwner\")\r\n  invitations     AgencyInvitation[] @relation(\"InvitationsReceived\")\r\n  invitationsSent AgencyInvitation[] @relation(\"InvitationsSent\")\r\n\r\n  applications      AgencyApplication[]  @relation(\"ApplicantApplications\")\r\n  applicationEvents ApplicationEvent[]\r\n  applicationNotes  ApplicationNote[]\r\n  documents         Document[]           @relation(\"UserDocuments\")\r\n  notifications     Notification[]\r\n  auditLogs         AuditLog[]\r\n  reportsFiled      Report[]             @relation(\"ReportsFiled\")\r\n  reportsAgainst    Report[]             @relation(\"ReportsAgainst\")\r\n  resetTokens       PasswordResetToken[]\r\n}\r\n\r\n// Staff role only. Buying, renting and publishing are capabilities of every\r\n// account; agency membership lives in agencyId / agencyRole.\r\nenum Role {\r\n  client\r\n  admin\r\n}\r\n\r\nenum AccountType {\r\n  individual\r\n  agency\r\n}\r\n\r\nenum UserStatus {\r\n  active\r\n  suspended\r\n  deactivated\r\n}\r\n\r\nenum AgencyRole {\r\n  owner\r\n  manager\r\n  agent\r\n}\r\n\r\nmodel Post {\r\n  id            Int          @id @default(autoincrement())\r\n  title         String\r\n  price         Int\r\n  images        Json // Store image URLs as a JSON array\r\n  address       String\r\n  city          String\r\n  district      String\r\n  bedroom       Int\r\n  bathroom      Int\r\n  latitude      String\r\n  longitude     String\r\n  type          Type\r\n  property      Property\r\n  propertyType  PropertyType\r\n  status        PostStatus   @default(pending)\r\n  reviewNote    String?      @db.Text\r\n  reviewedAt    DateTime?\r\n  availability  Availability @default(available)\r\n  // Taken offline by whoever lists it; the moderation status is left untouched\r\n  hiddenByOwner Boolean      @default(false)\r\n  featured      Boolean      @default(false)\r\n  createdAt     DateTime     @default(now())\r\n  updatedAt     DateTime     @default(now()) @updatedAt\r\n  // Ownership: an agency listing belongs to the agency (agencyId); otherwise\r\n  // to the individual in userId.\r\n  agencyId      Int?\r\n  agency        Agency?      @relation(fields: [agencyId], references: [id], onDelete: SetNull)\r\n  // Responsible account: the individual owner, or the assigned agent of an\r\n  // agency listing (null = unassigned, handled by the agency's leads)\r\n  userId        Int?\r\n  user          User?        @relation(fields: [userId], references: [id], onDelete: SetNull)\r\n  // Who published it; never changes\r\n  createdById   Int?\r\n  createdBy     User?        @relation(\"PostCreator\", fields: [createdById], references: [id], onDelete: SetNull)\r\n  reports       Report[]\r\n  postDetail    PostDetail?\r\n  savedPosts    SavedPost[]\r\n  inquiries     Inquiry[]\r\n  viewLog       PostView[]\r\n\r\n  @@index([agencyId, status])\r\n  @@index([userId, status])\r\n}\r\n\r\n// Listings are hidden from the public until an admin approves them\r\nenum PostStatus {\r\n  pending\r\n  approved\r\n  rejected\r\n  unpublished // taken offline by the team, can be republished\r\n  archived // kept for the record, no longer on the market\r\n}\r\n\r\nenum Availability {\r\n  available\r\n  under_offer\r\n  sold\r\n  rented\r\n}\r\n\r\nenum Type {\r\n  buy\r\n  rent\r\n}\r\n\r\nenum Property {\r\n  commercial\r\n  residential\r\n}\r\n\r\nenum PropertyType {\r\n  // Commercial Types\r\n  office\r\n  retail\r\n  hospitality\r\n  industrial\r\n\r\n  // Residential Types\r\n  apartment\r\n  individual_house\r\n  traditional_house\r\n  other_residential\r\n}\r\n\r\nmodel PostDetail {\r\n  id        Int     @id @default(autoincrement())\r\n  desc      String  @db.Text\r\n  utilities String?\r\n  pet       String?\r\n  size      Int?\r\n  Furnished String?\r\n  post      Post    @relation(fields: [postId], references: [id], onDelete: Cascade)\r\n  postId    Int     @unique\r\n  views     Int     @default(0) // 👈 Add this line\r\n  Matricule String?\r\n\r\n  // New Nearby Facilities\r\n  primarySchool  String?\r\n  kindergarten   String?\r\n  university     String?\r\n  carPark        String?\r\n  transportation String?\r\n  highSchool     String?\r\n  middleSchool   String?\r\n  mosque         String?\r\n  pharmacy       String?\r\n  commercialArea String?\r\n}\r\n\r\n// One row per viewer per listing per day; the unique key makes counting idempotent\r\nmodel PostView {\r\n  id        Int      @id @default(autoincrement())\r\n  postId    Int\r\n  viewerKey String   @db.VarChar(80)\r\n  day       Int // days since the Unix epoch (UTC)\r\n  createdAt DateTime @default(now())\r\n  post      Post     @relation(fields: [postId], references: [id], onDelete: Cascade)\r\n\r\n  @@unique([postId, viewerKey, day])\r\n}\r\n\r\nmodel SavedPost {\r\n  id        Int      @id @default(autoincrement())\r\n  user      User     @relation(fields: [userId], references: [id])\r\n  post      Post     @relation(fields: [postId], references: [id])\r\n  userId    Int\r\n  postId    Int\r\n  createdAt DateTime @default(now())\r\n\r\n  @@unique([userId, postId]) // Composite unique constraint\r\n}\r\n\r\n// Many-to-many join table for users and chats\r\nmodel Chat {\r\n  id          Int        @id @default(autoincrement()) // Use Int for ID with auto increment\r\n  createdAt   DateTime   @default(now())\r\n  lastMessage String?    @db.Text\r\n  messages    Message[]\r\n  users       ChatUser[]\r\n  // Conversations about a property hang off an inquiry; older ones are\r\n  // plain person-to-person chats\r\n  inquiry     Inquiry?\r\n}\r\n\r\nmodel ChatUser {\r\n  chatId     Int\r\n  userId     Int\r\n  // Everything the other person sent after this is unread for this user\r\n  lastReadAt DateTime?\r\n  chat       Chat      @relation(fields: [chatId], references: [id], onDelete: Cascade)\r\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\r\n\r\n  @@id([chatId, userId])\r\n}\r\n\r\nmodel Message {\r\n  id        Int      @id @default(autoincrement())\r\n  text      String   @db.Text\r\n  userId    Int\r\n  chatId    Int\r\n  chat      Chat     @relation(fields: [chatId], references: [id], onDelete: Cascade)\r\n  createdAt DateTime @default(now())\r\n\r\n  // polling asks for \"messages in this chat after X\"\r\n  @@index([chatId, createdAt])\r\n}\r\n\r\n// A client's question or visit request about one property, routed from the\r\n// listing: agency listings go to the agency (and the assigned agent),\r\n// individual listings to their owner. One per client and property.\r\nmodel Inquiry {\r\n  id            Int           @id @default(autoincrement())\r\n  type          InquiryType   @default(question)\r\n  status        InquiryStatus @default(open)\r\n  clientId      Int\r\n  client        User          @relation(\"InquiryClient\", fields: [clientId], references: [id], onDelete: Cascade)\r\n  postId        Int?\r\n  post          Post?         @relation(fields: [postId], references: [id], onDelete: SetNull)\r\n  // kept so the history still reads well if the listing is deleted\r\n  postTitle     String\r\n  agencyId      Int?\r\n  agency        Agency?       @relation(fields: [agencyId], references: [id], onDelete: SetNull)\r\n  ownerId       Int?\r\n  owner         User?         @relation(\"InquiryOwner\", fields: [ownerId], references: [id], onDelete: SetNull)\r\n  assignedToId  Int?\r\n  assignedTo    User?         @relation(\"InquiryAssignee\", fields: [assignedToId], references: [id], onDelete: SetNull)\r\n  message       String?       @db.Text\r\n  contactPhone  String?       @db.VarChar(40)\r\n  preferredDate String?       @db.VarChar(20)\r\n  preferredTime String?       @db.VarChar(20)\r\n  confirmedDate String?       @db.VarChar(20)\r\n  confirmedTime String?       @db.VarChar(20)\r\n  declineReason String?       @db.Text\r\n  chatId        Int?          @unique\r\n  chat          Chat?         @relation(fields: [chatId], references: [id], onDelete: SetNull)\r\n  createdAt     DateTime      @default(now())\r\n  updatedAt     DateTime      @default(now()) @updatedAt\r\n\r\n  @@unique([clientId, postId])\r\n  @@index([agencyId, status])\r\n  @@index([ownerId, status])\r\n  @@index([assignedToId, status])\r\n}\r\n\r\nenum InquiryType {\r\n  question\r\n  visit\r\n}\r\n\r\nenum InquiryStatus {\r\n  open\r\n  scheduled // visit confirmed\r\n  closed\r\n  declined\r\n  cancelled // by the client\r\n}\r\n\r\n// ---------- Agencies ----------\r\n\r\n// The live, verified record of an agency. Created when an application is\r\n// approved (or by an admin directly). The flat agency fields on User are kept\r\n// in sync so the public marketplace keeps working unchanged.\r\nmodel Agency {\r\n  id                 Int                @id @default(autoincrement())\r\n  ownerId            Int?               @unique\r\n  owner              User?              @relation(\"AgencyOwner\", fields: [ownerId], references: [id], onDelete: SetNull)\r\n  entityType         EntityType         @default(legal_entity)\r\n  legalName          String\r\n  tradeName          String\r\n  legalForm          String?\r\n  rcNumber           String?\r\n  nif                String?\r\n  nis                String?\r\n  articleImposition  String?\r\n  address            String?\r\n  wilaya             String?\r\n  commune            String?\r\n  phone              String?\r\n  email              String?\r\n  website            String?\r\n  logo               String?\r\n  about              String?            @db.Text\r\n  repFullName        String?\r\n  repPosition        String?\r\n  repPhone           String?\r\n  repEmail           String?\r\n  approvalNumber     String?\r\n  approvalWilaya     String?\r\n  approvalIssueDate  DateTime?\r\n  approvalExpiryDate DateTime?\r\n  // Operational status and verification are separate decisions\r\n  status             AgencyStatus       @default(active)\r\n  statusReason       String?            @db.Text\r\n  verification       AgencyVerification @default(pending)\r\n  verificationNote   String?            @db.Text\r\n  verifiedAt         DateTime?\r\n  createdAt          DateTime           @default(now())\r\n  updatedAt          DateTime           @default(now()) @updatedAt\r\n\r\n  members      User[]              @relation(\"AgencyMembers\")\r\n  posts        Post[]\r\n  inquiries    Inquiry[]\r\n  invitations  AgencyInvitation[]\r\n  applications AgencyApplication[]\r\n  documents    Document[]\r\n}\r\n\r\nenum AgencyStatus {\r\n  active\r\n  suspended\r\n}\r\n\r\n// The badge shows only while verified, the agency is active and its\r\n// agrément hasn't expired (lib/agency.js isAgencyVerified)\r\nenum AgencyVerification {\r\n  pending\r\n  verified\r\n  revoked\r\n}\r\n\r\n// An agency asking an existing account to join. Nobody joins an agency\r\n// without accepting.\r\nmodel AgencyInvitation {\r\n  id          Int              @id @default(autoincrement())\r\n  agencyId    Int\r\n  agency      Agency           @relation(fields: [agencyId], references: [id], onDelete: Cascade)\r\n  userId      Int\r\n  user        User             @relation(\"InvitationsReceived\", fields: [userId], references: [id], onDelete: Cascade)\r\n  agencyRole  AgencyRole       @default(agent)\r\n  status      InvitationStatus @default(pending)\r\n  invitedById Int?\r\n  invitedBy   User?            @relation(\"InvitationsSent\", fields: [invitedById], references: [id], onDelete: SetNull)\r\n  expiresAt   DateTime\r\n  respondedAt DateTime?\r\n  createdAt   DateTime         @default(now())\r\n\r\n  @@index([userId, status])\r\n  @@index([agencyId, status])\r\n}\r\n\r\nenum InvitationStatus {\r\n  pending\r\n  accepted\r\n  declined\r\n  revoked\r\n}\r\n\r\n// Natural person (personne physique) or legal entity (personne morale)\r\nenum EntityType {\r\n  natural_person\r\n  legal_entity\r\n}\r\n\r\nmodel AgencyApplication {\r\n  id          Int               @id @default(autoincrement())\r\n  applicantId Int\r\n  applicant   User              @relation(\"ApplicantApplications\", fields: [applicantId], references: [id], onDelete: Cascade)\r\n  agencyId    Int?\r\n  agency      Agency?           @relation(fields: [agencyId], references: [id], onDelete: SetNull)\r\n  status      ApplicationStatus @default(draft)\r\n  entityType  EntityType        @default(legal_entity)\r\n\r\n  // A. Agency\r\n  legalName         String?\r\n  tradeName         String?\r\n  legalForm         String?\r\n  rcNumber          String?\r\n  nif               String?\r\n  nis               String?\r\n  articleImposition String?\r\n  address           String?\r\n  wilaya            String?\r\n  commune           String?\r\n  phone             String?\r\n  email             String?\r\n  website           String?\r\n  logo              String?\r\n\r\n  // B. Legal representative / manager\r\n  repFullName    String?\r\n  repBirthDate   DateTime?\r\n  repNationality String?\r\n  repIdNumber    String?\r\n  repPhone       String?\r\n  repEmail       String?\r\n  repPosition    String?\r\n\r\n  // C. Professional authorization\r\n  approvalNumber      String?\r\n  approvalWilaya      String?\r\n  approvalIssueDate   DateTime?\r\n  approvalExpiryDate  DateTime?\r\n  qualifiedPersonName String? // holder of the qualification, if not the representative\r\n  qualification       String? // diploma or professional title relied on\r\n\r\n  message        String?   @db.Text // from the applicant\r\n  checklist      Json? // admin-only document verification ticks\r\n  requestMessage String?   @db.Text // what the team asked for (applicant sees it)\r\n  decisionNote   String?   @db.Text // shown to the applicant with the decision\r\n  submittedAt    DateTime?\r\n  reviewedAt     DateTime?\r\n  reviewerId     Int?\r\n  createdAt      DateTime  @default(now())\r\n  updatedAt      DateTime  @default(now()) @updatedAt\r\n\r\n  events    ApplicationEvent[]\r\n  notes     ApplicationNote[]\r\n  documents Document[]\r\n\r\n  @@index([status])\r\n}\r\n\r\nenum ApplicationStatus {\r\n  draft\r\n  submitted\r\n  under_review\r\n  info_required\r\n  resubmitted\r\n  approved\r\n  rejected\r\n}\r\n\r\n// Every status change and upload, in order. `message` is visible to the applicant.\r\nmodel ApplicationEvent {\r\n  id            Int                @id @default(autoincrement())\r\n  applicationId Int\r\n  application   AgencyApplication  @relation(fields: [applicationId], references: [id], onDelete: Cascade)\r\n  type          String             @db.VarChar(40)\r\n  fromStatus    ApplicationStatus?\r\n  toStatus      ApplicationStatus?\r\n  message       String?            @db.Text\r\n  actorId       Int?\r\n  actor         User?              @relation(fields: [actorId], references: [id], onDelete: SetNull)\r\n  createdAt     DateTime           @default(now())\r\n}\r\n\r\n// Internal notes: never sent to the applicant\r\nmodel ApplicationNote {\r\n  id            Int               @id @default(autoincrement())\r\n  applicationId Int\r\n  application   AgencyApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\r\n  authorId      Int?\r\n  author        User?             @relation(fields: [authorId], references: [id], onDelete: SetNull)\r\n  body          String            @db.Text\r\n  createdAt     DateTime          @default(now())\r\n}\r\n\r\n// Private uploads (legal documents, report screenshots). Files live outside any\r\n// public path and are only streamed through authorized endpoints.\r\nmodel Document {\r\n  id            Int                @id @default(autoincrement())\r\n  kind          String             @db.VarChar(40)\r\n  originalName  String\r\n  mimeType      String             @db.VarChar(100)\r\n  size          Int\r\n  storageKey    String             @unique @db.VarChar(120)\r\n  sha256        String             @db.VarChar(64)\r\n  applicationId Int?\r\n  application   AgencyApplication? @relation(fields: [applicationId], references: [id], onDelete: Cascade)\r\n  agencyId      Int?\r\n  agency        Agency?            @relation(fields: [agencyId], references: [id], onDelete: SetNull)\r\n  reportId      Int?\r\n  report        Report?            @relation(fields: [reportId], references: [id], onDelete: Cascade)\r\n  userId        Int?\r\n  user          User?              @relation(\"UserDocuments\", fields: [userId], references: [id], onDelete: Cascade)\r\n  uploadedById  Int?\r\n  createdAt     DateTime           @default(now())\r\n}\r\n\r\n// ---------- Platform ----------\r\n\r\nmodel Notification {\r\n  id        Int                  @id @default(autoincrement())\r\n  audience  NotificationAudience\r\n  userId    Int?\r\n  user      User?                @relation(fields: [userId], references: [id], onDelete: Cascade)\r\n  type      String               @db.VarChar(50)\r\n  title     String\r\n  body      String?              @db.Text\r\n  link      String?\r\n  readAt    DateTime?\r\n  createdAt DateTime             @default(now())\r\n\r\n  @@index([audience, readAt])\r\n  @@index([userId, readAt])\r\n}\r\n\r\n// admin = the shared team inbox; user = one account's own notifications\r\nenum NotificationAudience {\r\n  admin\r\n  user\r\n}\r\n\r\nmodel AuditLog {\r\n  id         Int      @id @default(autoincrement())\r\n  actorId    Int?\r\n  actor      User?    @relation(fields: [actorId], references: [id], onDelete: SetNull)\r\n  action     String   @db.VarChar(60)\r\n  entityType String   @db.VarChar(40)\r\n  entityId   Int?\r\n  summary    String\r\n  details    Json?\r\n  ip         String?  @db.VarChar(64)\r\n  createdAt  DateTime @default(now())\r\n\r\n  @@index([entityType, entityId])\r\n  @@index([createdAt])\r\n}\r\n\r\nmodel Report {\r\n  id               Int          @id @default(autoincrement())\r\n  kind             ReportKind\r\n  reason           String\r\n  details          String?      @db.Text\r\n  reporterId       Int?\r\n  reporter         User?        @relation(\"ReportsFiled\", fields: [reporterId], references: [id], onDelete: SetNull)\r\n  reporterName     String?\r\n  reporterEmail    String?\r\n  postId           Int?\r\n  post             Post?        @relation(fields: [postId], references: [id], onDelete: SetNull)\r\n  reportedUserId   Int?\r\n  reportedUser     User?        @relation(\"ReportsAgainst\", fields: [reportedUserId], references: [id], onDelete: SetNull)\r\n  reportedUserText String?\r\n  status           ReportStatus @default(open)\r\n  resolution       String?      @db.Text\r\n  resolvedAt       DateTime?\r\n  resolvedById     Int?\r\n  createdAt        DateTime     @default(now())\r\n  documents        Document[]\r\n\r\n  @@index([status])\r\n}\r\n\r\nenum ReportKind {\r\n  user\r\n  post\r\n}\r\n\r\nenum ReportStatus {\r\n  open\r\n  resolved\r\n  dismissed\r\n}\r\n\r\n// Key/value platform settings edited from the dashboard (see lib/settings.js)\r\nmodel Setting {\r\n  key         String   @id @db.VarChar(60)\r\n  value       Json\r\n  updatedById Int?\r\n  updatedAt   DateTime @default(now()) @updatedAt\r\n}\r\n\r\nmodel PasswordResetToken {\r\n  id        Int       @id @default(autoincrement())\r\n  userId    Int\r\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\r\n  tokenHash String    @unique @db.VarChar(64)\r\n  expiresAt DateTime\r\n  usedAt    DateTime?\r\n  createdAt DateTime  @default(now())\r\n}\r\n";
